    "🛡️ {c}: đến, đá, không thua, nâng cúp. Một mùa giải gọn gàng như một đường chuyền.",
    "🛡️ Thất bại đã quên địa chỉ nhà {c} trong suốt mùa này. Kết quả: vô địch, bất bại.",
